<?php
declare(strict_types=1);

// Gestión de simulacros.
// Docentes crean exámenes y estudiantes responden, con resultados guardados en la base de datos.
require __DIR__.'/../includes/auth.php';require_login();require_once __DIR__.'/../config/database.php';csrf_check();
$me=$_SESSION['user'];$uid=(int)$me['id'];$role=(string)$me['role'];$flash='';$active=null;$questions=[];
function exam_expired(array $attempt,array $config): bool{return strtotime((string)$attempt['started_at'])+$config['duration_minutes']*60<=time();}
function finish_exam(PDO $pdo,int $attemptId,int $studentId): void {
 $q=$pdo->prepare('SELECT ea.id,ea.exam_id,ec.duration_minutes,ea.started_at FROM exam_attempts ea JOIN exam_configs ec ON ec.exam_id=ea.exam_id WHERE ea.id=? AND ea.student_id=? AND ea.finished_at IS NULL FOR UPDATE');$q->execute([$attemptId,$studentId]);$a=$q->fetch();if(!$a)return;
 $qs=$pdo->prepare('SELECT q.id,q.answer_key,q.type,c.id competency_id FROM exam_questions x JOIN questions q ON q.id=x.question_id JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id WHERE x.exam_id=?');$qs->execute([$a['exam_id']]);$all=$qs->fetchAll();$answers=$pdo->prepare('SELECT id,answer FROM exam_answers WHERE attempt_id=? AND question_id=?');$save=$pdo->prepare('INSERT INTO exam_answers(attempt_id,question_id,answer,is_correct) VALUES(?,?,?,?)');$correct=0;$count=count($all);
 foreach($all as $question){$answers->execute([$attemptId,$question['id']]);$existing=$answers->fetch();$ans=$existing?(string)$existing['answer']:'';$isCorrect=$ans!==''&&strcasecmp(trim($ans),trim((string)$question['answer_key']))===0;if($existing){$pdo->prepare('UPDATE exam_answers SET is_correct=? WHERE id=?')->execute([$isCorrect,$existing['id']]);}else{$save->execute([$attemptId,$question['id'],$ans,$isCorrect]);}$pdo->prepare('INSERT INTO student_competency_progress(student_id,competency_id,attempts,correct_count) VALUES(?,?,1,?) ON DUPLICATE KEY UPDATE attempts=attempts+1,correct_count=correct_count+VALUES(correct_count)')->execute([$studentId,$question['competency_id'],$isCorrect?1:0]);$correct+=(int)$isCorrect;}
 $score=$count?round($correct*100/$count,2):0;$pdo->prepare('UPDATE exam_attempts SET score=?,finished_at=NOW() WHERE id=? AND student_id=? AND finished_at IS NULL')->execute([$score,$attemptId,$studentId]);
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 try{
  if(in_array($role,['teacher','admin'],true)&&$action==='exam_create'){
   $title=trim((string)($_POST['title']??''));$grade=filter_var($_POST['grade_level']??null,FILTER_VALIDATE_INT);$duration=filter_var($_POST['duration']??null,FILTER_VALIDATE_INT);$attemptLimit=filter_var($_POST['attempt_limit']??null,FILTER_VALIDATE_INT);$ids=array_values(array_unique(array_map('intval',(array)($_POST['question_ids']??[]))));
   if(mb_strlen($title)<3||mb_strlen($title)>180||$grade===false||$grade<5||$grade>11||$duration===false||$duration<5||$duration>240||$attemptLimit===false||$attemptLimit<1||$attemptLimit>5||count($ids)<1||count($ids)>100)throw new RuntimeException('Revisa los datos. Selecciona entre 1 y 100 preguntas aprobadas del mismo grado.');
   $marks=implode(',',array_fill(0,count($ids),'?'));$v=$pdo->prepare("SELECT id FROM questions WHERE id IN ({$marks}) AND grade_level=? AND review_status='approved'");$v->execute([...$ids,$grade]);if(isset($_POST['random_order']))shuffle($ids);if(count($v->fetchAll())!==count($ids))throw new RuntimeException('Alguna pregunta no estÃ¡ aprobada o no corresponde al grado elegido.');
   $pdo->beginTransaction();try{$pdo->prepare('INSERT INTO exams(owner_id,title) VALUES(?,?)')->execute([$uid,$title]);$eid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO exam_configs(exam_id,grade_level,duration_minutes,attempt_limit,random_order,published,opens_at,closes_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$eid,$grade,$duration,$attemptLimit,isset($_POST['random_order'])?1:0,isset($_POST['published'])?1:0,($_POST['opens_at']??'')?date('Y-m-d H:i:s',strtotime((string)$_POST['opens_at'])):null,($_POST['closes_at']??'')?date('Y-m-d H:i:s',strtotime((string)$_POST['closes_at'])):null]);$pos=1;foreach($ids as $qid)$pdo->prepare('INSERT INTO exam_questions(exam_id,question_id,position) VALUES(?,?,?)')->execute([$eid,$qid,$pos++]);audit_event($pdo,$uid,'exam.created',['exam_id'=>$eid]);$pdo->commit();$flash='Simulacro creado.'.(isset($_POST['published'])?' Publicado para el grado elegido.':' QuedÃ³ como borrador.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
  }elseif($role==='student'&&$action==='exam_start'){$eid=(int)($_POST['exam_id']??0);$q=$pdo->prepare("SELECT e.id,ec.* FROM exams e JOIN exam_configs ec ON ec.exam_id=e.id WHERE e.id=? AND ec.published=1 AND ec.grade_level=? AND (ec.opens_at IS NULL OR ec.opens_at<=NOW()) AND (ec.closes_at IS NULL OR ec.closes_at>=NOW())");$q->execute([$eid,$me['grade_level']??0]);$exam=$q->fetch();if(!$exam)throw new RuntimeException('El simulacro no estÃ¡ disponible para tu grado o estÃ¡ fuera de fecha.');$pending=$pdo->prepare('SELECT id FROM exam_attempts WHERE exam_id=? AND student_id=? AND finished_at IS NULL ORDER BY id DESC LIMIT 1');$pending->execute([$eid,$uid]);$attemptId=$pending->fetchColumn();if(!$attemptId){$count=$pdo->prepare('SELECT COUNT(*) FROM exam_attempts WHERE exam_id=? AND student_id=?');$count->execute([$eid,$uid]);if((int)$count->fetchColumn()>=(int)$exam['attempt_limit'])throw new RuntimeException('Ya utilizaste tus intentos permitidos.');$pdo->prepare('INSERT INTO exam_attempts(exam_id,student_id,started_at) VALUES(?,?,NOW())')->execute([$eid,$uid]);$attemptId=(int)$pdo->lastInsertId();}header('Location: simulacros.php?attempt='.(int)$attemptId);exit;
  }elseif($role==='student'&&in_array($action,['exam_answer','exam_finish'],true)){$attemptId=(int)($_POST['attempt_id']??0);$q=$pdo->prepare('SELECT ea.id,ea.exam_id,ea.started_at,ec.duration_minutes,ec.grade_level FROM exam_attempts ea JOIN exam_configs ec ON ec.exam_id=ea.exam_id JOIN exams e ON e.id=ea.exam_id WHERE ea.id=? AND ea.student_id=? AND ea.finished_at IS NULL AND ec.published=1');$q->execute([$attemptId,$uid]);$attempt=$q->fetch();if(!$attempt)throw new RuntimeException('El intento ya terminÃ³ o no te pertenece.');$pdo->beginTransaction();$examId=(int)$attempt['exam_id'];$minutes=(int)$attempt['duration_minutes'];if(strtotime($attempt['started_at'])+$minutes*60<=time()||$action==='exam_finish'){finish_exam($pdo,$attemptId,$uid);$pdo->commit();$flash='Simulacro finalizado. El resultado ya estÃ¡ guardado.';}else{$qid=(int)($_POST['question_id']??0);$answer=trim((string)($_POST['answer']??''));$qcheck=$pdo->prepare('SELECT q.id,q.type FROM exam_questions x JOIN questions q ON q.id=x.question_id WHERE x.exam_id=? AND q.id=?');$qcheck->execute([$examId,$qid]);$question=$qcheck->fetch();if(!$question||mb_strlen($answer)>1000)throw new RuntimeException('Respuesta no vÃ¡lida para este intento.');if($question['type']==='single_choice'){$o=$pdo->prepare('SELECT 1 FROM question_options WHERE question_id=? AND label=?');$o->execute([$qid,$answer]);if(!$o->fetchColumn())throw new RuntimeException('Selecciona una opciÃ³n de esta pregunta.');}$existing=$pdo->prepare('SELECT id FROM exam_answers WHERE attempt_id=? AND question_id=?');$existing->execute([$attemptId,$qid]);$answerId=$existing->fetchColumn();if($answerId)$pdo->prepare('UPDATE exam_answers SET answer=?,is_correct=0 WHERE id=?')->execute([$answer,$answerId]);else$pdo->prepare('INSERT INTO exam_answers(attempt_id,question_id,answer,is_correct) VALUES(?,?,?,0)')->execute([$attemptId,$qid,$answer]);$pdo->commit();$flash='Respuesta guardada.';}header('Location: simulacros.php?attempt='.$attemptId);exit;
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$flash=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar. Verifica el esquema y el contenido del simulacro.';}
}
if(in_array($role,['teacher','admin'],true)){$sql='SELECT e.id,e.title,ec.grade_level,ec.duration_minutes,ec.attempt_limit,ec.published,COUNT(x.question_id) question_count FROM exams e JOIN exam_configs ec ON ec.exam_id=e.id LEFT JOIN exam_questions x ON x.exam_id=e.id';if($role!=='admin')$sql.=' WHERE e.owner_id='.(int)$uid;$sql.=' GROUP BY e.id ORDER BY e.created_at DESC';$exams=$pdo->query($sql)->fetchAll();$q=$pdo->query("SELECT q.id,q.prompt,q.grade_level,s.name subject FROM questions q JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE q.review_status='approved' ORDER BY q.grade_level,s.name,q.id");$bank=$q->fetchAll();}
if($role==='student'&&isset($_GET['attempt'])){$q=$pdo->prepare('SELECT ea.*,e.title,ec.grade_level,ec.duration_minutes FROM exam_attempts ea JOIN exams e ON e.id=ea.exam_id JOIN exam_configs ec ON ec.exam_id=e.id WHERE ea.id=? AND ea.student_id=?');$q->execute([(int)$_GET['attempt'],$uid]);$active=$q->fetch();if($active){if($active['finished_at']===null&&strtotime($active['started_at'])+$active['duration_minutes']*60<=time()){$pdo->beginTransaction();finish_exam($pdo,(int)$active['id'],$uid);$pdo->commit();$q->execute([(int)$active['id'],$uid]);$active=$q->fetch();}$q=$pdo->prepare('SELECT q.id,q.prompt,q.type,q.answer_key,s.name subject FROM exam_questions x JOIN questions q ON q.id=x.question_id JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE x.exam_id=? ORDER BY x.position');$q->execute([$active['exam_id']]);$questions=$q->fetchAll();if($active['finished_at']===null){$q=$pdo->prepare('SELECT question_id,answer FROM exam_answers WHERE attempt_id=?');$q->execute([$active['id']]);$saved=[];foreach($q->fetchAll() as $a)$saved[$a['question_id']]=$a['answer'];foreach($questions as &$question){$question['saved']=$saved[$question['id']]??'';$o=$pdo->prepare('SELECT label,body FROM question_options WHERE question_id=? ORDER BY label');$o->execute([$question['id']]);$question['options']=$o->fetchAll();}unset($question);}}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulacros Â· Prossor AI</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="app-body"><main class="main-content"><header class="topbar"><a href="dashboard.php">â† Mi espacio</a><b>Simulacros</b></header><?php if($flash): ?><div class="notice flash"><?= h($flash) ?></div><?php endif; ?>
<?php if(in_array($role,['teacher','admin'],true)): ?><section class="welcome"><div><p class="eyebrow">BANCO EVALUATIVO</p><h1>Configurar simulacro</h1><p class="muted">Solo incluye preguntas aprobadas del grado seleccionado. La calificaciÃ³n se calcula en el servidor.</p></div></section><section class="panel"><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Nombre<input name="title" maxlength="180" required></label><label>Grado<select name="grade_level" required><?php for($g=5;$g<=11;$g++): ?><option value="<?= $g ?>"><?= $g ?>Â°</option><?php endfor; ?></select></label><label>DuraciÃ³n (minutos)<input type="number" name="duration" value="30" min="5" max="240"></label><label>Intentos permitidos<input type="number" name="attempt_limit" value="1" min="1" max="5"></label><label>Apertura (opcional)<input type="datetime-local" name="opens_at"></label><label>Cierre (opcional)<input type="datetime-local" name="closes_at"></label><label>Preguntas aprobadas (Ctrl para varias)<select name="question_ids[]" multiple required size="8"><?php foreach($bank as $question): ?><option value="<?= (int)$question['id'] ?>" data-grade="<?= (int)$question['grade_level'] ?>">G<?= (int)$question['grade_level'] ?> Â· <?= h($question['subject'].' Â· '.mb_strimwidth($question['prompt'],0,100,'â€¦')) ?></option><?php endforeach; ?></select></label><label><input type="checkbox" name="random_order" value="1" checked> Aleatorizar orden</label><label><input type="checkbox" name="published" value="1"> Publicar ahora</label><button class="button primary" name="action" value="exam_create">Guardar simulacro</button></form></section><?php foreach($exams as $exam): ?><section class="panel"><h2><?= h($exam['title']) ?></h2><p>Grado <?= (int)$exam['grade_level'] ?> Â· <?= (int)$exam['question_count'] ?> preguntas Â· <?= (int)$exam['duration_minutes'] ?> min Â· <?= (int)$exam['attempt_limit'] ?> intento(s) Â· <?= (int)$exam['published']?'Publicado':'Borrador' ?></p></section><?php endforeach; ?>
<?php elseif($role==='student'&&$active): ?><section class="welcome"><div><p class="eyebrow">SIMULACRO</p><h1><?= h($active['title']) ?></h1><p class="muted"><?= $active['finished_at']?'Resultado guardado':'Tiempo controlado por el servidor; respuestas guardadas al enviar cada pregunta.' ?></p></div></section><?php if($active['finished_at']): ?><section class="panel"><h2>Resultado: <?= h((string)$active['score']) ?>%</h2><p>Resultado de prÃ¡ctica basado en las preguntas del intento; no equivale a puntaje oficial ICFES.</p><?php foreach($questions as $q): $a=$pdo->prepare('SELECT answer,is_correct FROM exam_answers WHERE attempt_id=? AND question_id=?');$a->execute([$active['id'],$q['id']]);$ans=$a->fetch(); ?><article class="plan-row"><div><b><?= h($q['subject']) ?> Â· <?= $ans&&$ans['is_correct']?'Correcta':'Para repasar' ?></b><small><?= h($q['prompt']) ?><?php if($ans): ?> Â· Respuesta: <?= h($ans['answer']) ?><?php endif; ?></small></div></article><?php endforeach; ?></section><?php else: ?><div id="timer" class="notice" data-seconds="<?= max(0,strtotime($active['started_at'])+$active['duration_minutes']*60-time()) ?>"></div><?php foreach($questions as $index=>$q): $a=$pdo->prepare('SELECT answer FROM exam_answers WHERE attempt_id=? AND question_id=?');$a->execute([$active['id'],$q['id']]);$saved=$a->fetchColumn(); ?><section class="panel"><h2><?= (int)($index+1) ?>. <?= h($q['subject']) ?></h2><p><?= h($q['prompt']) ?></p><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="attempt_id" value="<?= (int)$active['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$q['id'] ?>"><?php if($q['type']==='single_choice'): ?><div class="options"><?php foreach($q['options'] as $opt): ?><label class="option"><input type="radio" name="answer" value="<?= h($opt['label']) ?>" <?= $saved===$opt['label']?'checked':'' ?> required><span><?= h($opt['label'].'. '.$opt['body']) ?></span></label><?php endforeach; ?></div><?php else: ?><input name="answer" maxlength="1000" value="<?= h((string)$saved) ?>" required><?php endif; ?><button class="mini-button" name="action" value="exam_answer">Guardar respuesta</button></form></section><?php endforeach; ?><form method="post" id="finish-exam" onsubmit="/* JavaScript: confirma antes de finalizar el simulacro. */ return confirm('Â¿Finalizar el simulacro ahora?')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="attempt_id" value="<?= (int)$active['id'] ?>"><button class="button primary" name="action" value="exam_finish">Finalizar simulacro</button></form><script>/* JavaScript: actualiza el temporizador y envia el intento al agotarse el tiempo. */ const timer=document.getElementById('timer');let remaining=Number(timer.dataset.seconds);const tick=()=>{if(remaining<=0){document.getElementById('finish-exam').requestSubmit();return;}timer.textContent='Tiempo restante: '+Math.floor(remaining/60)+' min '+(remaining%60)+' s';remaining--;setTimeout(tick,1000)};tick();</script><?php endif; ?>
<?php elseif($role==='student'): ?><section class="welcome"><div><p class="eyebrow">PREPARACIÃ“N ACADÃ‰MICA</p><h1>Simulacros disponibles</h1></div></section><?php $q=$pdo->prepare("SELECT e.id,e.title,ec.duration_minutes,ec.attempt_limit,ec.opens_at,ec.closes_at,(SELECT COUNT(*) FROM exam_attempts a WHERE a.exam_id=e.id AND a.student_id=?) used FROM exams e JOIN exam_configs ec ON ec.exam_id=e.id WHERE ec.published=1 AND ec.grade_level=? AND (ec.opens_at IS NULL OR ec.opens_at<=NOW()) AND (ec.closes_at IS NULL OR ec.closes_at>=NOW()) ORDER BY e.created_at DESC");$q->execute([$uid,$me['grade_level']??0]);$available=$q->fetchAll();if(!$available)echo '<section class="panel"><p class="muted">No hay simulacros publicados para tu grado en este momento.</p></section>';foreach($available as $exam): ?><section class="panel"><h2><?= h($exam['title']) ?></h2><p><?= (int)$exam['duration_minutes'] ?> min Â· Intentos usados <?= (int)$exam['used'] ?>/<?= (int)$exam['attempt_limit'] ?></p><?php if((int)$exam['used']<(int)$exam['attempt_limit']): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="exam_id" value="<?= (int)$exam['id'] ?>"><button class="button primary" name="action" value="exam_start">Empezar / continuar</button></form><?php endif; ?><?php $h=$pdo->prepare('SELECT id,score,finished_at FROM exam_attempts WHERE exam_id=? AND student_id=? AND finished_at IS NOT NULL ORDER BY finished_at DESC');$h->execute([$exam['id'],$uid]);foreach($h->fetchAll() as $attempt): ?><p>Intento <?= h(date('d/m/Y H:i',strtotime($attempt['finished_at']))) ?> Â· <?= h((string)$attempt['score']) ?>%</p><?php endforeach; ?></section><?php endforeach; ?><?php endif; ?></main></body></html>
